// CSD_RATIONALE_BEGIN
// This strategy targets a single SQL query enclosed in one visible constrained
// span. It tracks the ordinary visible output (`generated`), whether decoding is
// currently inside the SQL span, the active constrained SQL prefix
// (`currentConstrainedOut`), and a local `steps` counter for token-budget use.
// Outside the span, it first ensures entry into a visible constrained region:
// if the caller already emitted "<<", it uses EnterObservedConstrainedSpan;
// otherwise it opens one explicitly with OpenConstrainedSpan. Inside the span,
// it chooses among three parser-safe actions based on local observations:
// (1) if the parser state is narrow, use AdaptiveConstrainedStep with SQL token
// group preferences; (2) if the state is broader and multi-token progress is
// allowed, use ConstrainedSymbolInGenerated for chunked parser-valid progress;
// (3) if the prefix looks stalled by repetition, use SafeRepetitionPenaltyStep.
// Whenever the parser reports completeness, it closes the span with
// CloseConstrainedSpan. These tracked states and branch conditions keep the SQL
// text parser-valid while still allowing soft LM preferences and bounded
// multi-token progress.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: Before the loop, the preconditions establish validity of the
//   initial constrained state. In the outside-span branches, either we stay
//   outside (so the implication is vacuous), or we enter a span via
//   EnterObservedConstrainedSpan / OpenConstrainedSpan, both of which set
//   currentConstrainedOut := [], and parser.IsValidPrefix([]) holds by method
//   precondition. In the complete-prefix branch, CloseConstrainedSpan exits the
//   span, so the implication is again vacuous. In the repetition-penalty,
//   adaptive-step, and symbol branches, the helper returns either EOS or a
//   parser-valid extension/prefix; on non-EOS paths, AppendConstrainedToken or
//   ConstrainedSymbolInGenerated updates currentConstrainedOut to a valid prefix,
//   preserving the invariant.
// progress: EnterObservedConstrainedSpan consumes 0 steps and does not append,
//   so |generated| <= |generatedPrefix| + steps is unchanged. OpenConstrainedSpan
//   and CloseConstrainedSpan each consume 1 step and append at most one visible
//   delimiter, preserving the bound. SafeRepetitionPenaltyStep and
//   AdaptiveConstrainedStep each consume 1 step; if they return non-EOS, we
//   append at most one token, so visible growth is at most consumed budget.
//   ConstrainedSymbolInGenerated consumes `stepsUsed`; even if some consumed
//   tokens are EOS or rejected suffix tokens, its visible growth is at most the
//   consumed token budget, so |generated| <= |generatedPrefix| + steps remains
//   true after steps := steps + stepsUsed.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var sqlGroups := validTokenGroups;
var openCount := helpers.CountTokenOccurrences(generatedPrefix, "<<");
var closeCount := helpers.CountTokenOccurrences(generatedPrefix, ">>");

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if openCount > closeCount {
      var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := enteredGenerated;
      insideConstrainedOut := enteredInside;
      currentConstrainedOut := enteredCurrent;
      openCount := closeCount;
    } else {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      steps := steps + 1;
      openCount := openCount + 1;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    closeCount := closeCount + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var repeatedOpenParen := helpers.TokensSinceLastOccurrence(currentConstrainedOut, "(");
    var repeatedComma := helpers.TokensSinceLastOccurrence(currentConstrainedOut, ",");
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    var deadEndSoon := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);

    if deadEndSoon || repeatedOpenParen == 0 || repeatedComma == 0 {
      var nextRep := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
      );
      steps := steps + 1;
      if nextRep == eosToken {
        break;
      } else {
        var appendedGenerated1, appendedInside1, appendedCurrent1 := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, nextRep
        );
        generated := appendedGenerated1;
        insideConstrainedOut := appendedInside1;
        currentConstrainedOut := appendedCurrent1;
      }
    } else if stepTokenBudget > 1 && validCount > 12 {
      var remaining: nat := maxSteps - steps;
      var symbolBudget: nat := if stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolOut, hitEos, stepsUsed := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      insideConstrainedOut := true;
      currentConstrainedOut := symbolOut;
      steps := steps + stepsUsed;
      if hitEos {
        break;
      }
    } else {
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, sqlGroups, 4.0, 12, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated2, appendedInside2, appendedCurrent2 := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated2;
        insideConstrainedOut := appendedInside2;
        currentConstrainedOut := appendedCurrent2;
      }
    }
  }
}

cost := steps;

